    "cifra": "Intro: ||  Bb2 F/A | Dm Am7 Bb |  Bb/D Eb/G | F ||\n\n      Bb                              F\nSe Tu olhares, Senhor, pra dentro de mim,\n       Gm7             C\nNada encontrarás de bom.\n   Bb           C/Bb\nMas um desejo eu tenho,\n   F   C/E       Dm7\nDe ser transformado;\n  Gm7             F/A\nPreciso tanto do Teu perdão\nBb            Csus      C\nDá-me um novo coração.\n\nRefrão:\nF          Fsus     F/A       Bb        Gm7    C\nDá-me um coração igual ao Teu, meu Mestre,\nF          Eb/G      F/A      Bb\nDá-me um coração igual ao Teu:\n    Csus      C/Bb        Am7     Dm7\nCoração disposto a obede- cer,\n   Am7                  Dm7\nCumprir todo o Teu querer,\nGm7            Bb/C            F\nDá-me um coração igual ao Teu.\n\nPonte:\n C/E           C           Dm7\nEnsina-me a amar o meu irmão,\n     C                       F\nA olhar com Teus olhos, perdoar com Teu perdão,\n    Bb          C/Bb\n||: Enche-me com Teu Espírito,\nAm            Dm7              C   Bb\nEndireita os meus caminhos, oh Deus,\n                  Bb/C   1:  F\n               2:  C/D       D\nDá-me um novo coração.    :||\n\nRefrão c/subida de tom:\nG          Gsus     G/B       C       Am7    D\nDá-me um coração igual ao Teu, meu Mestre,\nG           F/A    G/B        C\nDá-me um coração igual ao Teu:\nTag   Dsus      D/C       Bm7    Em7\nCoração disposto a obedecer.\n  Bm7                  Em7\nCumprir todo o teu querer,\nAm7            C/D            G\nDá-me um coração igual ao Teu.",
