    "category": "Normal",
    "cifra": "Intro: ||:  A/D  D  |  A/D  D  |  E/A  A  |  E/A  A  :||\n\nEstrofe 1:\nA/D    D  A/D        D         E/A   A   E/A    A\nBendirei o     Senhor p’ra sem-pre;\nA/D     D       A/D    D     E/A    A  E/A    A\nTodo o tempo, Nele confiarei;\nA/D     D   A/D      D      E/A    A  E/A     A\nEle   me liber - tou do me - do;\nA/D       D   A/D        D      E/A      A   E/A   A\nOs meus pés, sobre a Rocha, colo - cou!\n\nPré-refrão 1:\nD9\nFirme ficarei,\n    Bm7        E\nE direi do Senhor\n\nRefrão:\n            A9           Bm7            D9         E4    E\nTu és meu escudo, minha força, minha porção, libertador;\n     A9             A9/C#            D9            E          (Intro)\nMeu abrigo, torre forte, meu socorro bem presente na aflição!\n\nEstrofe 2:\nA/D          D   A/D     D      E/A     A   E/A    A\nQuem tenho eu  lá no céu, senão a Ti?\nA/D      D    A/D      D     E/A      A   E/A    A\nNão há quem eu   deseje além de Ti!\n\n(Refrão)\n\nInstrumental: ||: Bm7  |  A/C#  |  F#m  |  E :||\n\nPré-refrão 2:\n  D9\nE em Ti sou feliz,\n  Bm7          E\nE direi do Senhor\n\n(Refrão)",
