    "cifra": "Intro: ||: D2  G  Bm  Asus4  A :||\n\nEstrofe 1:\nD2            G          Bm             Asus4           A\n     A minha rocha Tu és,    o meu conforto e provisão,\nD            G           Bm7      Asus4       A\n     Tu és a causa do meu ser.\n\nEstrofe 2:\nD2           G           Bm            Asus4            A\n     Da Tua graça provei,     da Tua vida     recebi\nD           G              Bm7       Asus4\n    Para habitar em Tua presen  -  ça!\n\nPré-refrão:\nGmaj7            D/F#           Bm         Am       G\n       E os sinais seguirão ao que crer em Ti,\n           D/F#         Bm11       Asus4       A\nPois Teu Espírito me guia -  rá.\nA/G             D/F#             Bm11\n        Farei tudo o que disseres,\n      Asus/C          G\nFarei Tua esta cidade,\n       D/F#           Bm11         Asus4       A\nE p’ra sempre cantarei     assim:\n\nRefrão:\nA          G        G/B           A/C#\n    Louvai Deus que Reina nas nações!\n    D/F#         G    Bm11          Asus4      A\nSeu nome é maior e Reina em poder!\nA          G        G/B           A/C#\n    Louvai Deus que Reina nas nações!\n  D/F#          G      Bm11             Asus4      A\nElevo a minha voz para Lhe agradecer.\n\nFim:\n   Asus              D    D2\n||:        Louvai Deus!  :||",
