    "cifra": "Intro: G7M(9) C7M G7M(9) C7M C/D\n\nEstrofe 1:\n      G7M                        C7M\nTanta coisa tenho feito para o meu próprio prazer\n        G7M                     C7M\nTenho andado a procura do meu próprio bem viver\n  B7/D#       Em7                   Bm7\nEnquanto existe tanta gente ansiosa por aí\n      C9             A/C#               C/D       D\nNão te conhecendo assim   como eu conheço a ti\n\nEstrofe 2:\n     G7M                          C7M\nO cha   -   mado que um dia tu fizeste a mim\n     G7M                   C7M\nE ao qual sem hesitar eu disse: \"Sim\"\nB/D#     Em7                          Bm7\nResso-ou   nos meus ouvidos como da primeira vez\n    C9           A/C#         C/D           D\nE a Ti Jesus eu novamente digo: \"Sim\"\n\nRefrão:\n    B7/D#       Em7\n||: Eis-me aqui,\n                  Bm7\nEu livre estou ao Teu  dispor\n    C9           C/D      D          G9   B7/D#\nPara onde Tu quise  -  res me enviar\n     Em7               Bm7\nMe coloco submisso a Ti, Senhor\n               C9             C/D     D     G9   Bsus4      B\n1ª vez: Para o Teu querer em mim reali - zar.\n               C9              C/D    D     G9\n2ª vez: Para o Teu querer em mim reali - zar :||",
