    "category": "Normal",
    "cifra": "Intro: | D A/D | G | Bm7 A9 | G2 |\n\nRefrão:\n           D           A/D          G2/B\nA cada manhã as misericórdias se renovam,\n          D/F#          A/E             G2\nA cada manhã as misericórdias se renovam,\n          Em7     A    G/B      D\nA cada manhã,     a cada manhã.\n\nD                A/C#           G        Bm7          A          G\nQuando as minhas forças se acabam, e a minha esperança no Senhor\n\n        Em7      D/F#      A                    G   Bm7        A\nParece não re – sis – tir, minh’alma se abate dentro de mim.\n\nMeu coração começa a se lembrar\n\nDaquilo que renova a esperança:\n\nAs misericórdias do Senhor não têm fim, grande é o seu amor!\n\nPonte:\n\nBm7      F#m          A\nMinha porção é o Senhor,\nEm/        D/F#            A\nA minha força é sua alegria,\nG/B        A/C#             Em7\nEle é a razão do meu louvor,\nG       D/F#             A\nInspiração da minha melodia,\nBm7       F#7           A\nEspero Nele a cada novo dia!\n\nA cada manhã, as misericórdias se renovam;\n\nA cada manhã as misericórdias se renovam;\n\nA cada manhã, a cada manhã!\n\n          B/E            A2/C#        A2     E\nAs misericórdias se renovam, a cada manhã.\n      B/E               A2/C#        A2      D2    | G D/F#    D2  | E\nAs misericórdias se renovam, a cada manhã.",
